import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import ItemCard from '../shared/ItemCard';
import Pagination from '../../components/pagination/Pagination';
import { fetchAPI } from '../../utils/api';

const Models = ({ manufacturerName, manufacturerLogo, onSelectModel }) => {
  const { search } = useLocation();
  const params = new URLSearchParams(search);
  const seriesId = params.get('series');

  // States for fetched data
  const [models, setModels] = useState([]);
  const [series, setSeries] = useState(null);
  const [manufacturer, setManufacturer] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch models, series, and manufacturer data
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);

        // Fetch series data
        const seriesResponse = await fetchAPI('series');
        if (!seriesResponse.ok) throw new Error('Failed to fetch series data');
        const seriesData = await seriesResponse.json();

        const selectedSeries = seriesData.series.find(s => s.id === parseInt(seriesId));
        if (!selectedSeries) throw new Error('Series not found');
        setSeries(selectedSeries);

        // Fetch manufacturer data
        const manufacturersResponse = await fetchAPI('manufacturers');
        if (!manufacturersResponse.ok) throw new Error('Failed to fetch manufacturers data');
        const manufacturersData = await manufacturersResponse.json();

        const selectedManufacturer = manufacturersData.manufacturers.find(m => parseInt(m.id) === parseInt(selectedSeries.manufacturerId));
        if (!selectedManufacturer) throw new Error('Manufacturer not found');
        setManufacturer(selectedManufacturer);

        // Fetch models data
        const modelsResponse = await fetchAPI('models');

        if (!modelsResponse.ok) throw new Error('Failed to fetch models data');
        const modelsData = await modelsResponse.json();

        const filtered = modelsData.models.filter(model => model.seriesId === parseInt(seriesId));
        setModels(filtered);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [seriesId]); // Dependency on seriesId ensures the effect re-runs if seriesId changes

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const modelsPerPage = 12;
  const totalPages = Math.ceil(models.length / modelsPerPage);
  const displayedModels = models.slice((currentPage - 1) * modelsPerPage, currentPage * modelsPerPage);

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  // Handle loading and error states
  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div className="container-fluid mb-5">
      <div className="row">
        <div className="d-flex align-items-center">
          <img
            src={manufacturerLogo || manufacturer?.logo}
            alt={manufacturerName || manufacturer?.name}
            className="img-fluid me-2 border"
            style={{ height: '100px' }}
          />
          <h4 className="ps-2">
            {manufacturerName || manufacturer?.name} <span className="fw-bold">Models</span>
          </h4>
        </div>
      </div>
      <div className="row d-flex flex-wrap p-2">
        {displayedModels.length > 0 ? (
          displayedModels.map((model) => (
            <ItemCard key={model.id} item={model} onSelect={() => onSelectModel(model)} />
          ))
        ) : (
          <div>No models found for the selected series.</div>
        )}
      </div>
      {models.length > modelsPerPage && (
        <div className="row">
          <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={handlePageChange} />
        </div>
      )}
    </div>
  );
};

export default Models;
